namespace {
lv_image_dsc_t make(const uint8_t *data) {
    lv_image_dsc_t image = {};
    image.header.magic = LV_IMAGE_HEADER_MAGIC;
    image.header.cf = LV_COLOR_FORMAT_RGB565A8;
    image.header.w = kSide;
    image.header.h = kSide;
    image.header.stride = kSide * 2;
    image.data_size = kBytes;
    image.data = data;
    return image;
}
}  // namespace

const lv_image_dsc_t &tile_icons::notebook() {
    static const lv_image_dsc_t image = make(notebook_data);
    return image;
}

const lv_image_dsc_t &tile_icons::todoist() {
    static const lv_image_dsc_t image = make(todoist_data);
    return image;
}
